import {request} from '../cms-api.js';
export async function renderAnalytics(container,online){
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
 container.append(el('p','A small, useful view of who finds your work. Counts begin when this update reaches your public site.','hint'));
 if(!online){container.append(el('p','Sign in as the owner to view real analytics. No sample numbers are shown.','empty-state'));return;}
 const controls=el('div',null,'analytics-controls'),label=el('label','Date range'),select=el('select');for(const n of [7,30,90]){const o=el('option','Last '+n+' days');o.value=n;o.selected=n===30;select.append(o);}label.append(select);const refresh=el('button','Refresh');controls.append(label,refresh);container.append(controls);
 const status=el('p','Loading audience data…','hint');status.setAttribute('role','status');const result=el('div');container.append(status,result);let generation=0;
 function table(title,rows,key){const p=el('section',null,'panel');p.append(el('h2',title));if(!rows.length){p.append(el('p','No activity in this period.','hint'));return p;}const t=el('table',null,'data-table'),head=el('thead'),tr=el('tr');tr.append(el('th',title),el('th','Count'));head.append(tr);t.append(head);const body=el('tbody');for(const row of rows){const r=el('tr');r.append(el('td',row[key]||'Direct / unknown'),el('td',Number(row.count).toLocaleString()));body.append(r);}t.append(body);p.append(t);return p;}
 async function load(){const ticket=++generation;refresh.disabled=true;status.textContent='Loading audience data…';try{const data=await request('/rest/v1/rpc/portfolio_analytics_summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period_days:Number(select.value)})},true);if(ticket!==generation)return;result.replaceChildren();const metrics=el('div',null,'metric-grid');for(const [title,value,detail] of [['Page views',data.views,'Public page loads'],['Visits (approx.)',data.visits,'Browser-tab sessions, reset daily'],['Project clicks',data.project_clicks,'Clicks on project destinations'],['Contact clicks',data.contact_clicks,'Email and social link clicks']]){const card=el('div',title,'stat');card.append(el('strong',Number(value).toLocaleString()),el('small',detail));metrics.append(card);}result.append(metrics);
 if(!data.views)result.append(el('p','No page views recorded yet. Once the update is deployed, public visits will appear here. Admin pages, previews and opted-out browsers are excluded.','empty-state'));
 const chart=el('section',null,'panel');chart.append(el('h2','Page views over time'));const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 760 190');svg.setAttribute('role','img');svg.setAttribute('aria-label','Daily page views. Exact values follow in the expandable table.');svg.classList.add('analytics-chart');const max=Math.max(1,...data.daily.map(d=>Number(d.count)));for(let i=0;i<4;i++){const l=document.createElementNS(ns,'line');l.setAttribute('x1','0');l.setAttribute('x2','760');l.setAttribute('y1',String(15+i*50));l.setAttribute('y2',String(15+i*50));l.setAttribute('stroke','#354236');svg.append(l);}const width=760/data.daily.length;data.daily.forEach((d,i)=>{const rect=document.createElementNS(ns,'rect'),h=Number(d.count)/max*150;for(const [key,value] of Object.entries({x:i*width+2,y:165-h,width:Math.max(2,width-4),height:h,rx:2,fill:'#c6d9ae'}))rect.setAttribute(key,String(value));const title=document.createElementNS(ns,'title');title.textContent=d.day+': '+d.count+' views';rect.append(title);svg.append(rect);});chart.append(svg);const caption=el('div',null,'chart-caption');caption.append(el('span',data.daily[0]?.day||''),el('span','UTC · peak '+max+'/day'),el('span',data.daily.at(-1)?.day||''));chart.append(caption);const details=el('details');details.append(el('summary','View daily counts'),table('Daily counts',data.daily,'day'));chart.append(details);result.append(chart);
 const tables=el('div',null,'analytics-tables');tables.append(table('Pages',data.pages,'page'),table('Referring websites',data.referrers,'referrer'),table('Devices',data.devices,'device'),table('Clicked destinations',data.targets,'target'));result.append(tables);result.append(el('p','Approximate visits are not unique people. A new tab or day may count again; blockers and privacy settings can reduce counts. Referrers contain hostnames only. No names, emails, raw IPs, full URLs or chat text are stored. Records are retained for up to 90 days and pruned on the next recorded event.','hint'));status.textContent='Updated '+new Date().toLocaleTimeString()+' · '+data.days+' days · UTC dates';}
 catch(e){if(ticket===generation){result.replaceChildren();status.textContent='Analytics could not load: '+e.message+' Retry with Refresh. If this is a new installation, apply backend/analytics-setup.sql.';}}
 finally{if(ticket===generation)refresh.disabled=false;}}
 select.onchange=load;refresh.onclick=load;await load();
}
